INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2900, 'forklift', '/''fɔːrklɪft/', 'noun', '{"zh-TW":["叉車；堆高機"],"en":["a vehicle with a forked device at the front used for lifting and transporting heavy loads"]}', NULL, 'operate a forklift / forklift certification / warehouse forklift', '[{"en":"All warehouse staff must hold a forklift certification before operating one.","zh-TW":"所有倉庫工作人員在操作叉車前必須持有叉車認證。"},{"en":"The forklift moved the heavy crates from the truck to the storage area.","zh-TW":"叉車將沉重的板條箱從卡車移到儲存區。"}]', NULL, NULL, 3, 2900, NULL),
(2901, 'form', '/fɔːrm/', 'noun / verb', '{"zh-TW":["形式；形成"],"en":["a type or kind; to create or establish"]}', NULL, 'application form / form a team', '[{"en":"Please complete the application form.","zh-TW":"請填寫申請表。"},{"en":"A committee was formed to review the policy.","zh-TW":"成立了一個委員會來審查政策。"}]', '{"noun":"form/formation","verb":"form","adjective":"formal"}', NULL, 1, 2901, NULL),
(2902, 'form of payment', '/fɔːrm əv ˈpeɪmənt/', 'noun', '{"zh-TW":["付款方式"],"en":["the method used to make a financial payment, such as cash, card, or transfer"]}', NULL, 'specify the form of payment / acceptable form of payment', '[{"en":"The invoice specifies wire transfer as the required form of payment.","zh-TW":"發票規定電匯為要求的付款方式。"},{"en":"Customers can choose their preferred form of payment at checkout.","zh-TW":"客戶可以在結帳時選擇其首選的付款方式。"}]', NULL, NULL, 5, 2902, NULL),
(2903, 'formal', '/ˈfɔːrməl/', 'adjective', '{"zh-TW":["正式的"],"en":["following established rules or conventions"]}', NULL, 'formal agreement/meeting', '[{"en":"A formal complaint was submitted.","zh-TW":"提交了一份正式投訴。"},{"en":"Dress code is formal for the event.","zh-TW":"活動的著裝要求是正式的。"}]', '{"noun":"formality","adjective":"formal","adverb":"formally"}', NULL, 2, 2903, NULL),
(2904, 'formal proposal', '/ˈfɔːrməl prəˈpoʊzəl/', 'noun', '{"zh-TW":["正式提案"],"en":["a written document presenting a detailed plan for consideration"]}', NULL, 'submit a formal proposal / prepare a formal proposal', '[{"en":"Please submit a formal proposal outlining costs and timelines.","zh-TW":"請提交概述成本和時間表的正式提案。"},{"en":"The formal proposal was reviewed by the procurement committee.","zh-TW":"正式提案由採購委員會審查了。"}]', NULL, NULL, 5, 2904, NULL),
(2905, 'formality', '/''fɔːrˈmæləti/', 'noun', '{"zh-TW":["正式；正式行為"],"en":["the practice of strictly following rules and conventions; a formal act or procedure"]}', NULL, 'social formality / business formality / observe formality', '[{"en":"In some cultures, maintaining formality in business interactions is very important.","zh-TW":"在某些文化中，在商業互動中保持正式是非常重要的。"},{"en":"She dispensed with the usual formality and addressed her clients by first name.","zh-TW":"她省去了通常的正式禮節，直呼客戶的名字。"}]', '{"adjective":"formal","adverb":"formally"}', NULL, 3, 2905, NULL),
(2906, 'formalize', '/ˈfɔːrməlaɪz/', 'verb', '{"zh-TW":["正式化；使成為正式"],"en":["to give something an official or formal status"]}', NULL, 'formalize an agreement / formalize a process / formalize procedures', '[{"en":"The partnership was formalized with a signed memorandum.","zh-TW":"合作關係通過簽署的備忘錄正式化了。"},{"en":"The company formalized its remote work policy after the pandemic.","zh-TW":"公司在疫情後正式確立了遠端工作政策。"}]', '{"noun":"formalization","adjective":"formalized"}', NULL, 3, 2906, 875),
(2907, 'format', '/ˈfɔːrmæt/', 'noun / verb', '{"zh-TW":["格式；格式化"],"en":["the arrangement of data; to arrange"]}', NULL, 'file/report format', '[{"en":"Please submit the report in PDF format.","zh-TW":"請以PDF格式提交報告。"},{"en":"The document needs to be formatted properly.","zh-TW":"文件需要正確格式化。"}]', '{"noun":"format/formatting","verb":"format"}', NULL, 2, 2907, NULL),
(2908, 'formative', '/ˈfɔːrmətɪv/', 'adjective', '{"zh-TW":["形成性的；早期的"],"en":["having a strong influence on the development of something"]}', NULL, 'formative assessment / formative years / formative experience', '[{"en":"Formative assessment helps teachers adjust instruction in real time.","zh-TW":"形成性評估幫助教師即時調整教學。"},{"en":"Her formative years were spent in a multicultural environment.","zh-TW":"她的成長歲月在多元文化環境中度過。"}]', NULL, NULL, 3, 2908, NULL),
(2909, 'formative assessment', '/''fɔːrmətɪv əˌsesmənt/', 'noun', '{"zh-TW":["形成性評量；過程評量"],"en":["ongoing assessment aimed at monitoring student learning and providing feedback during instruction"]}', NULL, 'use formative assessment / formative assessment strategy / benefit of formative assessment', '[{"en":"Formative assessment helps teachers adjust their teaching to better meet student needs.","zh-TW":"形成性評量幫助教師調整教學以更好地滿足學生需求。"},{"en":"Quizzes and class participation are common forms of formative assessment.","zh-TW":"測驗和課堂參與是常見的形成性評量形式。"}]', NULL, NULL, 5, 2909, NULL),
(2910, 'former', '/ˈfɔːrmər/', 'adjective', '{"zh-TW":["前任的；從前的"],"en":["having previously been"]}', NULL, 'former president/employee', '[{"en":"The former CEO founded a new startup.","zh-TW":"前任執行長創辦了一家新公司。"},{"en":"She is a former employee of ours.","zh-TW":"她是我們的前員工。"}]', '{"adjective":"former","adverb":"formerly"}', NULL, 2, 2910, NULL),
(2911, 'formidable', '/''fɔːrmɪdəbəl/', 'adjective', '{"zh-TW":["令人敬畏的；可怕的；難以對付的"],"en":["inspiring fear or respect through being impressively large, powerful, intense, or capable"]}', NULL, 'formidable challenge / formidable opponent / formidable task', '[{"en":"Entering the global market is a formidable challenge for any startup.","zh-TW":"進入全球市場對任何新創公司來說都是一個令人敬畏的挑戰。"},{"en":"She has built a formidable reputation as a tough negotiator.","zh-TW":"她建立了作為強硬談判者的令人敬畏的聲譽。"}]', '{"adverb":"formidably"}', NULL, 4, 2911, NULL),
(2912, 'formula', '/ˈfɔːrmjələ/', 'noun', '{"zh-TW":["公式；配方"],"en":["a mathematical rule; a method for achieving something"]}', NULL, 'winning formula', '[{"en":"There is no simple formula for success.","zh-TW":"成功沒有簡單的公式。"},{"en":"The formula calculates annual revenue.","zh-TW":"該公式計算年收入。"}]', '{"noun":"formula/formulation","verb":"formulate"}', NULL, 3, 2912, NULL),
(2913, 'formulate', 'ˈfɔːrmjʊleɪt', 'verb', '{"zh-TW":["制定；擬定","構想"],"en":["to create or develop a plan","to express precisely"]}', NULL, 'formulate a strategy/formulate a response', '[{"en":"We need to formulate a clear policy.","zh-TW":"我們需要制定明確的政策。"}]', '{"noun":"formulation","adjective":"formulated"}', NULL, 3, 2913, 685),
(2914, 'forthright', '/''fɔːrθˌraɪt/', 'adjective', '{"zh-TW":["坦誠的；直率的"],"en":["direct and outspoken; frank and candid"]}', NULL, 'forthright feedback / forthright manner / be forthright', '[{"en":"She appreciated his forthright feedback because it helped her improve quickly.","zh-TW":"她欣賞他坦率的反饋，因為它幫助她快速進步。"},{"en":"A forthright leader communicates goals and concerns clearly without ambiguity.","zh-TW":"直率的領導者能夠清晰地溝通目標和關切，沒有模糊性。"}]', '{"adverb":"forthrightly","noun":"forthrightness"}', NULL, 4, 2914, NULL),
(2915, 'fortified food', '/''fɔːrtɪfaɪd fuːd/', 'noun', '{"zh-TW":["強化食品；添加營養素的食品"],"en":["food that has had nutrients added to it that do not naturally occur in it"]}', NULL, 'consume fortified food / fortified cereal / fortified milk', '[{"en":"Fortified milk contains added vitamin D to support bone health.","zh-TW":"強化牛奶含有額外添加的維生素D，有助於骨骼健康。"},{"en":"Many breakfast cereals are fortified foods with added vitamins and minerals.","zh-TW":"許多早餐穀物是添加了維生素和礦物質的強化食品。"}]', NULL, NULL, 5, 2915, NULL),
(2916, 'fortify', '/''fɔːrtɪfaɪ/', 'verb', '{"zh-TW":["強化；添加營養素"],"en":["to add vitamins or minerals to food in order to make it more nutritious"]}', NULL, 'fortify with vitamins / fortify milk / fortify cereal', '[{"en":"Orange juice is often fortified with calcium and vitamin D.","zh-TW":"橙汁通常會添加鈣和維生素D以強化其營養。"},{"en":"Food manufacturers fortify cereals with iron to help address nutritional deficiencies.","zh-TW":"食品製造商在穀物中添加鐵質以幫助解決營養缺乏問題。"}]', '{"adjective":"fortified","noun":"fortification"}', NULL, 3, 2916, NULL),
(2917, 'fortress', '/''fɔːtrɪs/', 'noun', '{"zh-TW":["要塞；堡壘"],"en":["a military stronghold, especially a strongly fortified town"]}', NULL, 'ancient fortress / visit a fortress / coastal fortress', '[{"en":"The fortress was built on a hilltop to defend the city from invasion.","zh-TW":"這座要塞建在山頂上，保護城市免受入侵。"},{"en":"The medieval fortress now serves as a popular tourist attraction.","zh-TW":"這座中世紀堡壘現在是熱門的旅遊景點。"}]', NULL, NULL, 3, 2917, NULL),
(2918, 'fortuitous', '/''fɔːrˌtjuːɪtəs/', 'adjective', '{"zh-TW":["偶然的；幸運的"],"en":["happening by a fortunate chance; occurring by luck rather than by design"]}', NULL, 'fortuitous meeting / fortuitous discovery / fortuitous event', '[{"en":"Their fortuitous meeting at a conference led to a successful business partnership.","zh-TW":"他們在會議上的偶然相遇帶來了成功的商業合作。"},{"en":"The company''s success was partly the result of fortuitous timing in a rising market.","zh-TW":"公司的成功部分是在上升市場中偶然時機的結果。"}]', '{"adverb":"fortuitously","noun":"fortuity"}', NULL, 4, 2918, NULL),
(2919, 'fortune', '/ˈfɔːrtʃən/', 'noun', '{"zh-TW":["財富；命運"],"en":["a large amount of money; luck"]}', NULL, 'make a fortune', '[{"en":"He made a fortune in real estate.","zh-TW":"他在房地產賺了大錢。"},{"en":"Fortune 500 companies attract top talent.","zh-TW":"財富500強公司吸引頂尖人才。"}]', '{"noun":"fortune","adjective":"fortunate","adverb":"fortunately"}', NULL, 3, 2919, NULL),
(2920, 'forum selection', '/ˈfɔːrəm sɪˈlekʃən/', 'noun', '{"zh-TW":["管轄法院選擇"],"en":["a contract clause specifying which court will resolve disputes"]}', NULL, 'forum selection clause / forum selection agreement / enforce forum selection', '[{"en":"The contract included a forum selection clause designating Hong Kong courts.","zh-TW":"合約包含指定香港法院的管轄法院選擇條款。"},{"en":"Courts generally enforce valid forum selection clauses in commercial contracts.","zh-TW":"法院通常執行商業合約中有效的管轄法院選擇條款。"}]', NULL, NULL, 5, 2920, NULL),
(2921, 'forward', '/ˈfɔːrwərd/', 'verb', '{"zh-TW":["轉發；轉寄"],"en":["to send or pass on to another person"]}', NULL, 'forward an email / forward the proposal', '[{"en":"Please forward the attached report to your manager.","zh-TW":"請將附件報告轉發給您的經理。"},{"en":"I''ve forwarded your inquiry to the relevant department.","zh-TW":"我已將您的查詢轉發給相關部門。"}]', '{"adjective":"forward","adverb":"forward"}', NULL, 3, 2921, 126),
(2922, 'forward contract', '/ˈfɔːrwərd ˈkɒntrækt/', 'noun', '{"zh-TW":["遠期合約"],"en":["an agreement to buy or sell an asset at a future date at an agreed price"]}', NULL, 'enter a forward contract / forward contract price / foreign exchange forward', '[{"en":"They used a forward contract to lock in the exchange rate.","zh-TW":"他們使用遠期合約鎖定匯率。"},{"en":"A forward contract eliminates price uncertainty for both parties.","zh-TW":"遠期合約消除了雙方的價格不確定性。"}]', NULL, NULL, 5, 2922, NULL),
(2923, 'forward guidance', '/ˈfɔːrwərd ˈɡaɪdəns/', 'noun', '{"zh-TW":["前瞻指引"],"en":["a central bank''s communication about its expected future monetary policy actions"]}', NULL, 'provide forward guidance / central bank forward guidance', '[{"en":"The central bank''s forward guidance indicated rates would remain low for two years.","zh-TW":"中央銀行的前瞻指引表明利率將在兩年內保持低位。"},{"en":"Forward guidance reduces market uncertainty and stabilizes investor expectations.","zh-TW":"前瞻指引減少了市場不確定性並穩定了投資者預期。"}]', NULL, NULL, 5, 2923, NULL),
(2924, 'forward integration', '/ˈfɔːrwərd ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["向前整合；向下游整合"],"en":["a strategy where a company expands to control distribution or retail activities"]}', NULL, 'pursue forward integration / forward integration strategy', '[{"en":"The manufacturer opened retail stores as part of its forward integration strategy.","zh-TW":"製造商作為其向前整合策略的一部分開設了零售店。"},{"en":"Forward integration allows producers to capture more value closer to the end consumer.","zh-TW":"向前整合允許生產者在更接近最終消費者的地方獲取更多價值。"}]', '{"opposite":"backward integration"}', NULL, 5, 2924, NULL),
(2925, 'forward-looking', 'ˈfɔːrwərd ˈlʊkɪŋ', 'adjective', '{"zh-TW":["前瞻性的；有遠見的","積極進取的"],"en":["planning for the future","optimistic and progressive"]}', NULL, 'forward-looking company/forward-looking strategy', '[{"en":"This is a forward-looking initiative.","zh-TW":"這是一個具有前瞻性的計畫。"}]', NULL, NULL, 5, 2925, NULL),
(2926, 'forwarder', '/ˈfɔːrwərdər/', 'noun', '{"zh-TW":["貨運代理商；承攬運送業者"],"en":["a company that organizes shipments on behalf of importers or exporters"]}', NULL, 'freight forwarder / appoint a forwarder / forwarder services', '[{"en":"They hired a freight forwarder to handle the customs documentation.","zh-TW":"他們聘請了貨運代理商處理海關文件。"},{"en":"The forwarder coordinated the entire shipment from factory to port.","zh-TW":"貨運代理商協調了從工廠到港口的整個運輸過程。"}]', '{"full":"freight forwarder"}', NULL, 3, 2926, NULL),
(2927, 'fossil fuel', '/ˈfɒsəl fjuːəl/', 'noun', '{"zh-TW":["化石燃料"],"en":["natural fuels such as coal, oil, and natural gas"]}', NULL, 'burn fossil fuels / fossil fuel dependency', '[{"en":"The world is trying to reduce its dependence on fossil fuels.","zh-TW":"世界各地都在努力減少對化石燃料的依賴。"},{"en":"Burning fossil fuels releases greenhouse gases into the atmosphere.","zh-TW":"燃燒化石燃料會向大氣層釋放溫室氣體。"}]', NULL, NULL, 4, 2927, NULL),
(2928, 'fossil fuel phase-out', '/ˈfɒsəl fjuːəl feɪz aʊt/', 'noun', '{"zh-TW":["化石燃料淘汰"],"en":["the gradual elimination of fossil fuels from energy systems"]}', NULL, 'fossil fuel phase-out timeline / accelerate fossil fuel phase-out / just fossil fuel phase-out', '[{"en":"A rapid fossil fuel phase-out is essential to limiting global warming to 1.5°C.","zh-TW":"快速淘汰化石燃料對於將全球暖化限制在1.5°C至關重要。"},{"en":"The fossil fuel phase-out must be managed to protect energy workers.","zh-TW":"化石燃料淘汰必須妥善管理以保護能源工人。"}]', NULL, NULL, 5, 2928, NULL),
(2929, 'foster', '/ˈfɑːstər/', 'verb', '{"zh-TW":["促進；培養"],"en":["to encourage or promote the development of"]}', NULL, 'foster growth/innovation', '[{"en":"The program fosters entrepreneurship.","zh-TW":"該計畫促進創業精神。"},{"en":"We aim to foster a culture of innovation.","zh-TW":"我們旨在培養創新文化。"}]', '{"verb":"foster"}', NULL, 2, 2929, NULL),
(2930, 'foul', '/''faʊl/', 'noun', '{"zh-TW":["犯規；違規動作"],"en":["an action in a sport that is contrary to the rules"]}', NULL, 'commit a foul / call a foul / technical foul', '[{"en":"The referee called a foul on the player for tripping his opponent.","zh-TW":"裁判因一名球員絆倒對手而判其犯規。"},{"en":"Accumulating too many fouls results in automatic ejection from the game.","zh-TW":"累積過多犯規導致自動被驅逐出比賽。"}]', '{"verb":"foul"}', NULL, 1, 2930, NULL),
(2931, 'found', '/faʊnd/', 'verb', '{"zh-TW":["創立；成立"],"en":["to establish an organization"]}', NULL, 'found a company', '[{"en":"The company was founded in 1985.","zh-TW":"公司成立於1985年。"},{"en":"She founded a successful charity.","zh-TW":"她創立了一個成功的慈善機構。"}]', '{"noun":"founder/foundation","verb":"found"}', NULL, 2, 2931, NULL),
(2932, 'foundation', '/faʊnˈdeɪʃən/', 'noun', '{"zh-TW":["基礎；基金會"],"en":["the basis for something; an organization for charity"]}', NULL, 'lay the foundation', '[{"en":"Education is the foundation of success.","zh-TW":"教育是成功的基礎。"},{"en":"The foundation donated $1 million to research.","zh-TW":"基金會捐贈了100萬美元用於研究。"}]', '{"noun":"foundation","verb":"found"}', NULL, 4, 2932, 127),
(2933, 'fraction', '/ˈfrækʃən/', 'noun', '{"zh-TW":["一小部分；分數"],"en":["a small part of something"]}', NULL, 'a fraction of', '[{"en":"Only a fraction of applicants were accepted.","zh-TW":"只有一小部分申請者被錄取。"},{"en":"It costs a fraction of the original price.","zh-TW":"它只花了原價的一小部分。"}]', '{"noun":"fraction","adjective":"fractional"}', NULL, 3, 2933, NULL),
(2934, 'fragile state', '/ˈfrædʒaɪl steɪt/', 'noun', '{"zh-TW":["脆弱國家"],"en":["a country experiencing severe political instability, conflict, or economic crisis"]}', NULL, 'assist fragile states / fragile state characteristics / fragile state governance', '[{"en":"Humanitarian organizations focus significant resources on fragile states.","zh-TW":"人道主義組織在脆弱國家集中投入大量資源。"},{"en":"Fragile states struggle to provide basic services and security to citizens.","zh-TW":"脆弱國家難以向公民提供基本服務和安全。"}]', NULL, NULL, 5, 2934, NULL),
(2935, 'frame', '/freɪm/', 'noun / verb', '{"zh-TW":["框架；構築"],"en":["a structure; to formulate"]}', NULL, 'time frame / frame a question', '[{"en":"What is the time frame for completion?","zh-TW":"完成的時間框架是什麼？"},{"en":"The question was framed carefully.","zh-TW":"問題被謹慎地構築。"}]', '{"noun":"frame/framework","verb":"frame"}', NULL, 2, 2935, NULL),
(2936, 'frame narrative', '/freɪm ˈnærətɪv/', 'noun', '{"zh-TW":["框架敘事"],"en":["a story within a story structure used as a narrative device"]}', NULL, 'use frame narrative / frame narrative technique / frame narrative structure', '[{"en":"The Canterbury Tales uses a frame narrative to link diverse stories together.","zh-TW":"《坎特伯雷故事集》使用框架敘事將多樣的故事連接在一起。"},{"en":"A frame narrative allows the author to present multiple perspectives.","zh-TW":"框架敘事允許作者呈現多個觀點。"}]', NULL, NULL, 5, 2936, NULL),
(2937, 'framework', '/ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["框架；架構"],"en":["a basic structure underlying a system"]}', NULL, 'legal/regulatory framework', '[{"en":"We need a clear framework for decision-making.","zh-TW":"我們需要一個明確的決策框架。"},{"en":"The project operates within a legal framework.","zh-TW":"該項目在法律框架內運作。"}]', '{"noun":"framework"}', NULL, 3, 2937, 877),
(2938, 'framework agreement', '/ˈfreɪmwɜːrk əˈɡriːmənt/', 'noun', '{"zh-TW":["框架協議；骨架合約"],"en":["a master agreement setting general terms for future individual contracts"]}', NULL, 'sign a framework agreement / operate under a framework agreement', '[{"en":"A framework agreement was established for all software purchases.","zh-TW":"為所有軟體採購建立了框架協議。"},{"en":"The framework agreement simplified the procurement of recurring services.","zh-TW":"框架協議簡化了定期服務的採購。"}]', NULL, NULL, 5, 2938, NULL),
(2939, 'franchise', '/ˈfræntʃaɪz/', 'noun / verb', '{"zh-TW":["特許經營權；加盟"],"en":["a license to sell products under a brand name"]}', NULL, 'franchise agreement/owner', '[{"en":"He owns a fast-food franchise.","zh-TW":"他擁有一家速食加盟店。"},{"en":"The brand is looking to franchise internationally.","zh-TW":"該品牌正在尋求國際特許經營。"}]', '{"noun":"franchise/franchisee/franchisor","verb":"franchise"}', NULL, 3, 2939, NULL),
(2940, 'franchise agreement', '/ˈfrænʧaɪz əˈɡriːmənt/', 'noun', '{"zh-TW":["特許經營協議"],"en":["a legal contract granting a franchisee the right to use a franchisor''s brand"]}', NULL, 'sign a franchise agreement / franchise agreement terms', '[{"en":"The franchise agreement outlines territory, royalties, and operational standards.","zh-TW":"特許經營協議概述了區域、特許使用費和運營標準。"},{"en":"Violating the franchise agreement may result in termination.","zh-TW":"違反特許經營協議可能導致終止。"}]', NULL, NULL, 5, 2940, NULL),
(2941, 'franchise fee', '/ˈfrænˌtʃaɪz fiː/', 'noun', '{"zh-TW":["特許經營費"],"en":["a fee paid to use a franchise''s brand and business model"]}', NULL, 'pay a franchise fee / franchise fee structure', '[{"en":"The franchise fee covers the right to use the brand and systems.","zh-TW":"特許經營費包括使用品牌和系統的權利。"},{"en":"Prospective franchisees must pay an upfront franchise fee.","zh-TW":"準加盟商必須支付前期特許經營費。"}]', NULL, NULL, 5, 2941, NULL),
(2942, 'franchisee', '/ˌfræntʃaɪˈziː/', 'noun', '{"zh-TW":["加盟商；受許可人"],"en":["a person or company that has purchased the right to operate a franchised business"]}', NULL, 'recruit franchisees / support franchisees', '[{"en":"Each franchisee operates under the franchisor''s brand and standards.","zh-TW":"每個加盟商在特許經營者的品牌和標準下運營。"},{"en":"The franchisor provides training and marketing support to all franchisees.","zh-TW":"特許經營者為所有加盟商提供培訓和行銷支持。"}]', '{"opposite":"franchisor"}', NULL, 4, 2942, NULL),
(2943, 'franchisor', '/ˈfræntʃaɪzər/', 'noun', '{"zh-TW":["特許經營者；授予特許權者"],"en":["a company that grants franchises to others to operate under its brand"]}', NULL, 'become a franchisor / franchisor obligations', '[{"en":"The franchisor is responsible for protecting the brand across all franchise locations.","zh-TW":"特許經營者負責保護所有加盟地點的品牌。"},{"en":"A franchisor earns royalties from franchisees based on sales revenue.","zh-TW":"特許經營者根據銷售收入從加盟商處獲取版稅。"}]', '{"opposite":"franchisee"}', NULL, 4, 2943, NULL),
(2944, 'free', '/friː/', 'adjective / verb', '{"zh-TW":["免費的；自由的"],"en":["without cost; not restricted"]}', NULL, 'free of charge / free up', '[{"en":"The seminar is free of charge.","zh-TW":"研討會免費。"},{"en":"We need to free up some budget.","zh-TW":"我們需要騰出一些預算。"}]', '{"noun":"freedom","verb":"free","adjective":"free","adverb":"freely"}', NULL, 1, 2944, NULL),
(2945, 'free cash flow', '/friː kæʃ floʊ/', 'noun', '{"zh-TW":["自由現金流"],"en":["cash generated after accounting for capital expenditures"]}', NULL, 'generate free cash flow / positive free cash flow / free cash flow yield', '[{"en":"Strong free cash flow enables the company to fund dividends and buybacks.","zh-TW":"強勁的自由現金流使公司能夠資助股利和股票回購。"},{"en":"Investors prize companies that generate consistent free cash flow.","zh-TW":"投資者重視能夠持續產生自由現金流的公司。"}]', '{"abbreviation":"FCF"}', NULL, 5, 2945, NULL),
(2946, 'free rider', '/friː ˈraɪdər/', 'noun', '{"zh-TW":["搭便車者；免費獲益者"],"en":["someone who benefits from a public good or collective action without paying for it"]}', NULL, 'free rider problem / avoid free riders / free rider in economics', '[{"en":"The free rider problem makes it difficult to fund public goods through voluntary contributions.","zh-TW":"搭便車問題使得通過自願捐款來資助公共財變得困難。"},{"en":"Nations that reduce emissions while others do not face a free rider problem in climate policy.","zh-TW":"在其他國家不減排的情況下減少排放的國家面臨氣候政策中的搭便車問題。"}]', NULL, NULL, 4, 2946, NULL),
(2947, 'free rider problem', '/friː ˈraɪdər ˈprɒbləm/', 'noun', '{"zh-TW":["搭便車問題"],"en":["the tendency of individuals to benefit from collective resources without contributing"]}', NULL, 'address the free rider problem / free rider problem in public goods / overcome free rider problem', '[{"en":"The free rider problem makes it difficult to fund public goods like national defense.","zh-TW":"搭便車問題使資助國防等公共物品變得困難。"},{"en":"Membership organizations design incentives to minimize the free rider problem.","zh-TW":"會員組織設計激勵機制以最小化搭便車問題。"}]', NULL, NULL, 5, 2947, NULL),
(2948, 'free trade agreement', '/friː treɪd əˈɡriːmənt/', 'noun', '{"zh-TW":["自由貿易協定"],"en":["a pact between countries to reduce trade barriers"]}', NULL, 'sign a free trade agreement / negotiate a free trade agreement', '[{"en":"The free trade agreement eliminated tariffs on agricultural goods.","zh-TW":"自由貿易協定消除了農產品關稅。"},{"en":"Both countries benefit from the terms of the free trade agreement.","zh-TW":"兩國都受益於自由貿易協定的條款。"}]', '{"abbreviation":"FTA"}', NULL, 5, 2948, NULL),
(2949, 'free-range', '/friː reɪndʒ/', 'adjective', '{"zh-TW":["放養的；自由放牧的"],"en":["allowing animals to roam freely"]}', NULL, 'free-range chicken / free-range eggs', '[{"en":"The restaurant uses free-range chicken in all dishes.","zh-TW":"餐廳在所有菜餚中使用放養雞肉。"},{"en":"Free-range eggs have a richer flavor.","zh-TW":"放養雞蛋風味更豐富。"}]', NULL, NULL, 4, 2949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2950, 'freehold', '/''friːhəʊld/', 'noun', '{"zh-TW":["完全產權；永久業權"],"en":["permanent ownership of land or property, without time restriction"]}', NULL, 'freehold property / buy freehold / freehold ownership', '[{"en":"They purchased the freehold of the property, giving them full ownership of the land.","zh-TW":"他們購買了房產的永久業權，給予他們對土地的完全所有權。"},{"en":"Freehold properties are generally more expensive than leasehold ones.","zh-TW":"永久業權房產通常比租賃業權房產更昂貴。"}]', NULL, NULL, 3, 2950, NULL),
(2951, 'freemium', '/ˈfriːmiəm/', 'noun', '{"zh-TW":["免費增值模式"],"en":["a pricing model offering basic features free with paid premium upgrades"]}', NULL, 'freemium model / freemium strategy / convert freemium users', '[{"en":"The app uses a freemium model to attract users before upselling.","zh-TW":"該應用程式使用免費增值模式在向上銷售前吸引用戶。"},{"en":"Freemium services must balance free features with paid incentives.","zh-TW":"免費增值服務必須平衡免費功能與付費激勵。"}]', NULL, NULL, 3, 2951, NULL),
(2952, 'freight', '/freɪt/', 'noun', '{"zh-TW":["貨運；貨物"],"en":["goods transported in bulk by truck, train, ship, or aircraft"]}', NULL, 'air freight / sea freight / freight forwarding / freight cost', '[{"en":"Air freight was used for urgent shipments despite the higher cost.","zh-TW":"儘管成本較高，空運還是用於緊急貨物。"},{"en":"Sea freight is slower but much cheaper than air for bulky goods.","zh-TW":"海運比空運慢，但對大批量貨物便宜得多。"}]', '{"verb":"freight","adjective":"freight"}', NULL, 3, 2952, NULL),
(2953, 'freight broker', '/''freɪt ˌbrəʊkər/', 'noun', '{"zh-TW":["貨運經紀人；運輸中介"],"en":["an intermediary who connects shippers with carriers to arrange transportation of goods"]}', NULL, 'hire a freight broker / freight broker network / experienced freight broker', '[{"en":"A freight broker helped them find the most cost-effective carrier for the shipment.","zh-TW":"一位貨運經紀人幫助他們為貨物找到了最具成本效益的承運人。"},{"en":"Freight brokers save shippers time by negotiating rates and managing logistics.","zh-TW":"貨運經紀人通過談判費率和管理物流為托運人節省時間。"}]', NULL, NULL, 5, 2953, NULL),
(2954, 'freight cost', '/freɪt kɒst/', 'noun', '{"zh-TW":["運費；貨運成本"],"en":["the charges incurred for transporting goods from one place to another"]}', NULL, 'calculate freight costs / reduce freight costs', '[{"en":"Freight costs increased after fuel prices rose sharply.","zh-TW":"燃料價格急劇上漲後運費增加了。"},{"en":"Freight costs are included in the landed cost of imported goods.","zh-TW":"運費包含在進口商品的到岸成本中。"}]', '{"synonym":"shipping cost","synonym2":"carriage cost"}', NULL, 4, 2954, NULL),
(2955, 'freight forwarder', '/freɪt ˈfɔːrwɔːrdər/', 'noun', '{"zh-TW":["貨運代理商"],"en":["a company that organizes shipments on behalf of businesses"]}', NULL, 'use a freight forwarder / experienced freight forwarder', '[{"en":"The freight forwarder handled all customs paperwork.","zh-TW":"貨運代理商處理了所有海關文件。"},{"en":"Partnering with a reliable freight forwarder simplifies logistics.","zh-TW":"與可靠的貨運代理商合作簡化了物流。"}]', NULL, NULL, 5, 2955, NULL),
(2956, 'freight insurance', '/''freɪt ɪnˌʃʊərəns/', 'noun', '{"zh-TW":["運費保險；貨運保險"],"en":["insurance coverage for loss or damage to goods being transported"]}', NULL, 'purchase freight insurance / freight insurance claim / international freight insurance', '[{"en":"The company purchased freight insurance to cover all international shipments.","zh-TW":"公司購買了貨運保險以涵蓋所有國際貨物運輸。"},{"en":"Freight insurance is particularly important for high-value or fragile cargo.","zh-TW":"貨運保險對高價值或易碎貨物尤為重要。"}]', NULL, NULL, 5, 2956, NULL),
(2957, 'freight rate', '/''freɪt reɪt/', 'noun', '{"zh-TW":["運費率；貨運費率"],"en":["the price charged for transporting a unit of cargo from one location to another"]}', NULL, 'negotiate freight rate / freight rate increase / competitive freight rate', '[{"en":"The freight rate for shipping containers to Europe has tripled since last year.","zh-TW":"運輸貨櫃到歐洲的貨運費率自去年以來增加了三倍。"},{"en":"Shippers negotiate freight rates with carriers based on volume and contract length.","zh-TW":"托運人根據數量和合同期限與承運人協商貨運費率。"}]', NULL, NULL, 4, 2957, NULL),
(2958, 'freight terminal', '/''freɪt ˌtɜːrmɪnəl/', 'noun', '{"zh-TW":["貨運站；貨物轉運站"],"en":["a facility where freight is loaded, unloaded, and temporarily stored for further distribution"]}', NULL, 'operate a freight terminal / busy freight terminal / freight terminal facilities', '[{"en":"The city''s freight terminal handles over ten thousand containers per day.","zh-TW":"該市的貨運站每天處理超過一萬個貨櫃。"},{"en":"The new freight terminal was built with automated sorting and tracking technology.","zh-TW":"新貨運站建有自動化分揀和追蹤技術。"}]', NULL, NULL, 5, 2958, NULL),
(2959, 'frequent', '/ˈfriːkwənt/', 'adjective', '{"zh-TW":["頻繁的；經常的"],"en":["occurring often"]}', NULL, 'frequent traveler/visitor', '[{"en":"Frequent breaks improve productivity.","zh-TW":"頻繁休息可以提高生產力。"},{"en":"She is a frequent visitor to our office.","zh-TW":"她經常來我們辦公室。"}]', '{"noun":"frequency","adjective":"frequent","adverb":"frequently"}', NULL, 3, 2959, NULL),
(2960, 'frequent flyer', '/ˈfriːkwənt ˈflaɪər/', 'noun', '{"zh-TW":["常旅客；常飛旅客"],"en":["a person who travels by air often, usually in a loyalty program"]}', NULL, 'frequent flyer miles / frequent flyer program', '[{"en":"Frequent flyer miles can be redeemed for free flights.","zh-TW":"常旅客里程可以兌換免費機票。"},{"en":"She is a gold member of the airline''s frequent flyer program.","zh-TW":"她是航空公司常旅客計劃的金卡會員。"}]', NULL, NULL, 5, 2960, NULL),
(2961, 'frequently asked questions', '/ˈfriːkwəntli ɑːskt ˈkwestʃənz/', 'noun', '{"zh-TW":["常見問題"],"en":["a list of common questions and their answers"]}', NULL, 'check the FAQ / update the FAQ / FAQ page', '[{"en":"Check the FAQ page before contacting customer support.","zh-TW":"在聯繫客戶支援之前，請查看常見問題頁面。"},{"en":"The FAQ was updated to address recent customer inquiries.","zh-TW":"常見問題已更新以解答最近的客戶詢問。"}]', '{"abbreviation":"FAQ"}', NULL, 5, 2961, NULL),
(2962, 'fresh produce', '/''freʃ ˌprɒdjuːs/', 'noun', '{"zh-TW":["新鮮農產品；新鮮蔬果"],"en":["fresh fruits, vegetables, and other foods sold directly from the farm or market"]}', NULL, 'buy fresh produce / local fresh produce / seasonal fresh produce', '[{"en":"She shops at the farmers'' market every Saturday for fresh produce.","zh-TW":"她每個星期六在農夫市集購買新鮮農產品。"},{"en":"Using fresh produce rather than canned goods significantly improves the flavor of dishes.","zh-TW":"使用新鮮農產品而非罐裝食品可以顯著改善菜肴的風味。"}]', NULL, NULL, 5, 2962, NULL),
(2963, 'freshman', '/ˈfrɛʃmən/', 'noun', '{"zh-TW":["大一新生"],"en":["a first-year student"]}', NULL, 'freshman year / freshman orientation', '[{"en":"She''s a freshman at the university.","zh-TW":"她是大學一年級新生。"},{"en":"Freshman year can be challenging.","zh-TW":"大一可能充滿挑戰。"}]', NULL, NULL, 3, 2963, NULL),
(2964, 'friction', '/ˈfrɪkʃən/', 'noun', '{"zh-TW":["摩擦；阻力（比喻）"],"en":["resistance or conflict between people or processes; inefficiency"]}', NULL, 'reduce friction / internal friction / friction in supply chains', '[{"en":"Removing friction from the checkout process increases conversion rates.","zh-TW":"減少結帳流程中的摩擦提高了轉化率。"},{"en":"Trade friction between the two countries disrupted global supply chains.","zh-TW":"兩國之間的貿易摩擦擾亂了全球供應鏈。"}]', '{"adjective":"frictional","adverb":"frictionally"}', NULL, 3, 2964, NULL),
(2965, 'friend', '/frɛnd/', 'noun', '{"zh-TW":["朋友"],"en":["a person you know well and like"]}', NULL, 'make friends / close friend', '[{"en":"She made many friends at work.","zh-TW":"她在工作中交了很多朋友。"},{"en":"He is a close friend and business partner.","zh-TW":"他是好朋友也是商業夥伴。"}]', '{"noun":"friend","noun2":"friendship","adjective":"friendly","adjective2":"unfriendly"}', NULL, 2, 2965, NULL),
(2966, 'friendly', 'ˈfrɛndli', 'adjective', '{"zh-TW":["友好的；親切的","易用的"],"en":["kind and pleasant","not hostile"]}', NULL, 'user-friendly/customer-friendly', '[{"en":"The new interface is very user-friendly.","zh-TW":"新介面非常友好易用。"}]', '{"noun":"friendliness","adverb":"in a friendly way"}', NULL, 3, 2966, NULL),
(2967, 'fringe benefit', '/frɪndʒ ˈbenɪfɪt/', 'noun', '{"zh-TW":["附加福利；額外津貼"],"en":["an extra benefit given to employees beyond their salary"]}', NULL, 'fringe benefits include / taxable fringe benefits', '[{"en":"Fringe benefits such as gym memberships boost morale.","zh-TW":"健身房會員等附加福利提升員工士氣。"},{"en":"Some fringe benefits are subject to income tax.","zh-TW":"部分附加福利需繳納所得稅。"}]', NULL, NULL, 5, 2967, NULL),
(2968, 'frivolous', '/''frɪvələs/', 'adjective', '{"zh-TW":["輕率的；無聊的；不嚴肅的"],"en":["not having any serious purpose or value; lacking seriousness"]}', NULL, 'frivolous lawsuit / frivolous remark / frivolous behavior', '[{"en":"The court dismissed the frivolous lawsuit after determining it had no legal merit.","zh-TW":"法院在確定該案沒有法律依據後駁回了這起輕率的訴訟。"},{"en":"He was criticized for making frivolous comments during a serious meeting.","zh-TW":"他因在嚴肅的會議中發表輕率評論而受到批評。"}]', '{"adverb":"frivolously","noun":"frivolity"}', NULL, 3, 2968, NULL),
(2969, 'front', '/frʌnt/', 'noun / adjective', '{"zh-TW":["前面；前線"],"en":["the forward-facing part; leading position"]}', NULL, 'in front of / front desk', '[{"en":"The receptionist is at the front desk.","zh-TW":"接待員在前台。"},{"en":"Customer service is on the front line.","zh-TW":"客戶服務在第一線。"}]', '{"noun":"front","adjective":"front"}', NULL, 2, 2969, NULL),
(2970, 'front desk', '/frʌnt dɛsk/', 'noun', '{"zh-TW":["前台；接待台"],"en":["the reception area of a hotel"]}', NULL, 'check in at the front desk / contact the front desk', '[{"en":"Please collect your room key at the front desk.","zh-TW":"請在前台領取您的房間鑰匙。"},{"en":"The front desk is staffed 24 hours a day.","zh-TW":"前台全天24小時有工作人員。"}]', NULL, NULL, 4, 2970, NULL),
(2971, 'front-end loaded', '/frʌnt end ˈloʊdɪd/', 'adjective', '{"zh-TW":["前端費用偏高的；前期成本高的"],"en":["having a higher proportion of costs incurred at the beginning of a period or project"]}', NULL, 'front-end loaded fee structure / front-end loaded project', '[{"en":"The project was front-end loaded with heavy design and planning costs.","zh-TW":"該項目在設計和規劃方面前期成本偏高。"},{"en":"Front-end loaded loans have higher interest in early repayment periods.","zh-TW":"前期費用偏高的貸款在早期還款期間利息較高。"}]', NULL, NULL, 5, 2971, NULL),
(2972, 'front-running', '/ˈfrʌnt ˌrʌnɪŋ/', 'noun', '{"zh-TW":["搶先交易；超前交易"],"en":["the practice of a broker trading based on advance knowledge of pending client orders"]}', NULL, 'illegal front-running / front-running scandal / prohibit front-running', '[{"en":"Front-running by brokers who trade ahead of client orders is considered market manipulation.","zh-TW":"經紀商在客戶訂單之前進行交易的搶先交易行為被視為市場操縱。"},{"en":"The regulator investigated the firm for suspected front-running of large institutional orders.","zh-TW":"監管機構調查了該公司涉嫌搶先交易大型機構訂單的行為。"}]', NULL, NULL, 5, 2972, NULL),
(2973, 'fronting arrangement', '/ˈfrʌntɪŋ əˈreɪndʒmənt/', 'noun', '{"zh-TW":["先頭安排；前置安排"],"en":["an arrangement where a licensed insurer issues a policy on behalf of another entity"]}', NULL, 'enter a fronting arrangement / fronting arrangement requirements', '[{"en":"The company used a fronting arrangement to write insurance in markets where it lacked a license.","zh-TW":"公司在沒有許可證的市場使用了先頭安排來發行保單。"},{"en":"A fronting arrangement involves paying fees to the fronting insurer.","zh-TW":"先頭安排涉及向先頭保險公司支付費用。"}]', NULL, NULL, 5, 2973, NULL),
(2974, 'frontline workers', '/ˈfrʌntlaɪn ˈwɜːrkərz/', 'noun', '{"zh-TW":["前線工作者；一線人員"],"en":["employees who work directly with customers or in essential services"]}', NULL, 'support frontline workers / protect frontline workers / recognize frontline workers', '[{"en":"Frontline workers in healthcare faced extreme pressure during the pandemic.","zh-TW":"醫療保健領域的前線工作者在疫情期間面臨極大的壓力。"},{"en":"Compensation for frontline workers often does not reflect the risks and demands of their roles.","zh-TW":"前線工作者的薪酬通常不反映其職責的風險和要求。"}]', NULL, NULL, 5, 2974, NULL),
(2975, 'frost', '/frɒst/', 'noun', '{"zh-TW":["霜"],"en":["a thin layer of ice on a surface"]}', '{"root":{"text":"frost","meaning":"freeze (結凍)"},"logic":"結凍形成的薄冰層。"}', 'morning frost / frost damage / frostbite', '[{"en":"There was a heavy frost this morning.","zh-TW":"今天早上有很重的霜。"},{"en":"Frost can damage delicate plants.","zh-TW":"霜會損害嬌嫩的植物。"}]', '{"adjective":"frosty","noun":"frostbite"}', NULL, 2, 2975, NULL),
(2976, 'frugal', '/''fruːɡəl/', 'adjective', '{"zh-TW":["節儉的；省吃儉用的"],"en":["sparing or economical with regard to money or food; simple and plain"]}', NULL, 'frugal lifestyle / frugal with expenses / frugal company', '[{"en":"She lived a frugal lifestyle to save enough for her early retirement.","zh-TW":"她過著節儉的生活，為提前退休攢夠了錢。"},{"en":"The startup was frugal with spending in its early years to extend its runway.","zh-TW":"這家新創公司在早期節儉花費，以延長運作期限。"}]', '{"adverb":"frugally","noun":"frugality"}', NULL, 2, 2976, NULL),
(2977, 'fruit', '/fruːt/', 'noun', '{"zh-TW":["水果；成果"],"en":["food from a plant with seeds","a good result"]}', NULL, 'bear fruit / fruit of labor', '[{"en":"Our efforts are finally bearing fruit.","zh-TW":"我們的努力終於有了成果。"},{"en":"Fresh fruit is provided in the office.","zh-TW":"辦公室提供新鮮水果。"}]', '{"noun":"fruit","adjective":"fruitful","adjective2":"fruitless"}', NULL, 2, 2977, NULL),
(2978, 'frustrated', '/frʌˈstreɪtɪd/', 'adjective', '{"zh-TW":["沮喪的；受挫的"],"en":["feeling upset because of inability to change or achieve something"]}', '{"root":{"text":"frustr","meaning":"in vain (徒勞)"},"suffix":{"text":"-ated","meaning":"state (狀態)"},"logic":"感到徒勞的狀態，即「受挫的」。"}', 'feel frustrated / frustrated with', '[{"en":"He felt frustrated with the slow progress.","zh-TW":"他對緩慢的進度感到挫折。"},{"en":"Customers are frustrated by the long wait times.","zh-TW":"顧客對漫長的等待時間感到不滿。"}]', '{"noun":"frustration","verb":"frustrate","adjective":"frustrating"}', NULL, 4, 2978, NULL),
(2979, 'fulfill', '/fʊlˈfɪl/', 'verb', '{"zh-TW":["履行；實現"],"en":["to carry out a duty; to satisfy a requirement"]}', NULL, 'fulfill obligations/requirements', '[{"en":"The company fulfilled all contractual obligations.","zh-TW":"公司履行了所有合約義務。"},{"en":"We strive to fulfill customer expectations.","zh-TW":"我們努力滿足客戶期望。"}]', '{"noun":"fulfillment","verb":"fulfill"}', NULL, 3, 2979, 686),
(2980, 'fulfillment', '/fʊlˈfɪlmənt/', 'noun', '{"zh-TW":["訂單履行；完成"],"en":["the process of completing a customer order, including picking and shipping"]}', NULL, 'order fulfillment / fulfillment center / fulfillment speed / fulfillment process', '[{"en":"Same-day fulfillment became a key competitive advantage.","zh-TW":"當日訂單履行成為關鍵競爭優勢。"},{"en":"The company opened a new fulfillment center to serve the East Coast.","zh-TW":"公司開設了新的訂單履行中心以服務東海岸。"}]', '{"verb":"fulfill","adjective":"fulfilled"}', NULL, 4, 2980, 576),
(2981, 'full', '/fʊl/', 'adjective', '{"zh-TW":["滿的；完整的"],"en":["containing as much as possible","complete"]}', NULL, 'full-time / in full', '[{"en":"She works full-time at the firm.","zh-TW":"她在公司全職工作。"},{"en":"Payment must be made in full.","zh-TW":"必須全額付款。"}]', '{"adjective":"full","adverb":"fully","verb":"fulfill","noun":"fullness"}', NULL, 1, 2981, NULL),
(2982, 'full board', '/fʊl bɔːrd/', 'noun', '{"zh-TW":["全膳食服務"],"en":["accommodation including all meals"]}', NULL, 'full board package / full board rate', '[{"en":"The resort offers a full board package for families.","zh-TW":"度假村為家庭提供全膳食服務套餐。"},{"en":"Full board includes breakfast, lunch, and dinner.","zh-TW":"全膳食服務包含早餐、午餐和晚餐。"}]', NULL, NULL, 4, 2982, NULL),
(2983, 'full-time athlete', '/''fʊl taɪm ˌæθliːt/', 'noun', '{"zh-TW":["全職運動員；專業運動員"],"en":["a person who trains and competes as their primary occupation"]}', NULL, 'become a full-time athlete / support full-time athletes / schedule of a full-time athlete', '[{"en":"She quit her job to become a full-time athlete and focus on the upcoming Olympics.","zh-TW":"她辭去工作，成為一名全職運動員，專注於即將到來的奧運會。"},{"en":"Being a full-time athlete requires an enormous personal and financial commitment.","zh-TW":"成為全職運動員需要巨大的個人和財務承諾。"}]', NULL, NULL, 5, 2983, NULL),
(2984, 'full-time equivalent', '/fʊl taɪm ɪˈkwɪvələnt/', 'noun', '{"zh-TW":["全職當量"],"en":["a unit measuring the workload of an employed person in a way that makes workloads comparable"]}', NULL, 'calculate full-time equivalent / full-time equivalent headcount', '[{"en":"The project requires 10 full-time equivalent staff to complete on time.","zh-TW":"該項目需要10名全職當量員工才能按時完成。"},{"en":"Budgeting is simplified by expressing staffing needs in full-time equivalents.","zh-TW":"通過以全職當量表示人員需求來簡化預算編製。"}]', '{"abbreviation":"FTE"}', NULL, 5, 2984, NULL),
(2985, 'full-year results', '/fʊl jɪər rɪˈzʌlts/', 'noun', '{"zh-TW":["全年業績；年度業績"],"en":["the financial performance of a company over its entire fiscal year"]}', NULL, 'announce full-year results / full-year results presentation', '[{"en":"Full-year results showed a 15% increase in net profit.","zh-TW":"全年業績顯示淨利潤增加了15%。"},{"en":"Investors focused on full-year results to assess the CEO strategy.","zh-TW":"投資者關注全年業績以評估執行長的策略。"}]', NULL, NULL, 5, 2985, NULL),
(2986, 'function', '/ˈfʌŋkʃən/', 'noun / verb', '{"zh-TW":["功能；運作"],"en":["a purpose or role; to work properly"]}', NULL, 'key function / function as', '[{"en":"What is the function of this department?","zh-TW":"這個部門的功能是什麼？"},{"en":"The system is functioning normally.","zh-TW":"系統運作正常。"}]', '{"noun":"function/functionality","verb":"function","adjective":"functional"}', NULL, 3, 2986, NULL),
(2987, 'functional area', '/ˈfʌŋkʃənl ˈeəriə/', 'noun', '{"zh-TW":["職能領域；功能部門"],"en":["a department or division within an organization with a specific function"]}', NULL, 'manage a functional area / cross-functional area', '[{"en":"Each functional area submitted its budget request to finance.","zh-TW":"每個職能領域向財務部門提交了預算申請。"},{"en":"The new system affected every functional area in the company.","zh-TW":"新系統影響了公司的每個職能領域。"}]', NULL, NULL, 5, 2987, NULL),
(2988, 'functional currency', '/ˈfʌŋkʃənəl ˈkʌrənsi/', 'noun', '{"zh-TW":["功能貨幣"],"en":["the primary currency of a company''s operating environment used for accounting"]}', NULL, 'report in functional currency / functional currency translation', '[{"en":"The company''s functional currency is the US dollar for all reporting purposes.","zh-TW":"公司的功能貨幣在所有報告目的中為美元。"},{"en":"Transactions in other currencies are translated at the functional currency rate.","zh-TW":"其他貨幣的交易按功能貨幣匯率換算。"}]', NULL, NULL, 5, 2988, NULL),
(2989, 'fund', '/fʌnd/', 'noun / verb', '{"zh-TW":["基金；資助"],"en":["a sum of money for a purpose; to provide money"]}', NULL, 'raise/allocate funds', '[{"en":"The company raised funds for expansion.","zh-TW":"公司為擴張籌集了資金。"},{"en":"The project is funded by the government.","zh-TW":"該項目由政府資助。"}]', '{"noun":"fund/funding","verb":"fund"}', NULL, 1, 2989, 365),
(2990, 'fund management', '/fʌnd ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["基金管理"],"en":["professionally overseeing an investment portfolio to achieve a return"]}', NULL, 'outsource fund management / fund management company', '[{"en":"The pension fund outsourced its fund management to a specialist firm.","zh-TW":"退休金外包了其基金管理給專業公司。"},{"en":"Fund management requires balancing risk and return for investors.","zh-TW":"基金管理需要為投資者平衡風險和回報。"}]', NULL, NULL, 5, 2990, NULL),
(2991, 'fund manager', '/fʌnd ˈmænɪdʒər/', 'noun', '{"zh-TW":["基金經理"],"en":["a professional responsible for investment decisions within a fund"]}', NULL, 'appoint a fund manager / fund manager performance', '[{"en":"The fund manager achieved returns 3% above the benchmark index.","zh-TW":"基金經理取得了高出基準指數3%的回報。"},{"en":"Investors evaluate a fund manager''s track record before committing capital.","zh-TW":"投資者在投入資金前評估基金經理的業績記錄。"}]', NULL, NULL, 4, 2991, NULL),
(2992, 'fund of funds', '/fʌnd əv fʌndz/', 'noun', '{"zh-TW":["基金中的基金"],"en":["an investment fund that invests in a portfolio of other investment funds"]}', NULL, 'invest in a fund of funds / fund of funds strategy', '[{"en":"A fund of funds provides diversification across multiple managers.","zh-TW":"基金中的基金在多個管理人之間提供了多元化。"},{"en":"Fund of funds investors pay two layers of management fees.","zh-TW":"基金中的基金投資者支付兩層管理費。"}]', NULL, NULL, 5, 2992, NULL),
(2993, 'fundamental', '/ˌfʌndəˈmentəl/', 'adjective', '{"zh-TW":["基本的；根本的"],"en":["forming a necessary base; essential"]}', '{"root":{"text":"fund","meaning":"bottom/foundation (基礎)"},"suffix":{"text":"-amental","meaning":"relating to (相關的)"},"logic":"與基礎相關的，即「根本的」。"}', 'fundamental change/principle; fundamental principle / fundamental change / fundamental right', '[{"en":"Trust is fundamental to any business relationship.","zh-TW":"信任是任何商業關係的根本。"},{"en":"There are fundamental differences between the two plans.","zh-TW":"兩個計畫之間有根本的差異。"},{"en":"Respect is fundamental to any relationship.","zh-TW":"尊重是任何關係的根本。"},{"en":"There has been a fundamental change in policy.","zh-TW":"政策發生了根本性的改變。"}]', '{"noun":"fundamentals","adjective":"fundamental","adverb":"fundamentally"}', NULL, 4, 2993, NULL),
(2994, 'funding', 'ˈfʌndɪŋ', 'noun', '{"zh-TW":["資金；經費","撥款"],"en":["money provided for a purpose","financial support"]}', NULL, 'secure funding/government funding', '[{"en":"We secured additional funding for the project.","zh-TW":"我們為項目獲得了額外資金。"}]', '{"verb":"fund","adjective":"funded"}', NULL, 3, 2994, NULL),
(2995, 'funding gap', '/ˈfʌndɪŋ ɡæp/', 'noun', '{"zh-TW":["資金缺口"],"en":["the difference between what is available and what is needed for a project"]}', NULL, 'address the funding gap / identify the funding gap', '[{"en":"A funding gap of 5 million needed to be filled before construction.","zh-TW":"施工前需要填補500萬元的資金缺口。"},{"en":"The nonprofit sought donors to close its annual funding gap.","zh-TW":"非營利組織尋求捐款者填補其年度資金缺口。"}]', NULL, NULL, 4, 2995, NULL),
(2996, 'fungible', '/ˈfʌndʒɪbəl/', 'adjective', '{"zh-TW":["可互換的；等值可替代的"],"en":["(of goods or assets) able to be replaced or interchanged with an equivalent"]}', NULL, 'fungible asset / fungible commodity / fungible token', '[{"en":"Gold is a fungible commodity — one ounce equals another of the same purity.","zh-TW":"黃金是可互換的商品——相同純度的一盎司等於另一盎司。"},{"en":"Money is the quintessential fungible asset in economics.","zh-TW":"貨幣是經濟學中典型的可互換資產。"}]', '{"noun":"fungibility"}', NULL, 3, 2996, NULL),
(2997, 'funnel', '/ˈfʌnəl/', 'noun', '{"zh-TW":["漏斗；行銷漏斗"],"en":["the stages a customer goes through from awareness to purchase"]}', NULL, 'sales funnel / marketing funnel / top of funnel / bottom of funnel', '[{"en":"Most website visitors drop off at the top of the funnel.","zh-TW":"大多數網站訪客在漏斗頂端就流失了。"},{"en":"The team optimized the funnel to reduce drop-off at checkout.","zh-TW":"團隊優化了漏斗以減少結帳時的流失。"}]', '{"verb":"funnel"}', NULL, 2, 2997, NULL),
(2998, 'funny', '/ˈfʌni/', 'adjective', '{"zh-TW":["有趣的；好笑的"],"en":["causing laughter","strange or unexpected"]}', NULL, 'funny story / look funny', '[{"en":"He told a funny story at the dinner.","zh-TW":"他在晚餐上說了一個有趣的故事。"},{"en":"Something looks funny about these numbers.","zh-TW":"這些數字看起來有點奇怪。"}]', '{"adjective":"funny","adverb":"funnily","noun":"fun"}', NULL, 2, 2998, NULL),
(2999, 'furnish', '/ˈfɜːrnɪʃ/', 'verb', '{"zh-TW":["提供；配備"],"en":["to supply or provide; to equip with furniture"]}', NULL, 'furnish information/an office', '[{"en":"The apartment is fully furnished.","zh-TW":"公寓配備齊全。"},{"en":"Please furnish the required documents.","zh-TW":"請提供所需文件。"}]', '{"noun":"furnishing/furniture","verb":"furnish","adjective":"furnished"}', NULL, 3, 2999, 687);
