(3000, 'further', '/ˈfɜːrðər/', 'adverb / adjective / verb', '{"zh-TW":["進一步的；促進"],"en":["to a greater extent; to advance"]}', NULL, 'further information/investigation', '[{"en":"For further information, contact our office.","zh-TW":"如需進一步資訊，請聯繫我們的辦公室。"},{"en":"Education furthers career advancement.","zh-TW":"教育促進職業發展。"}]', '{"adjective":"further","adverb":"further/furthermore","verb":"further"}', NULL, 3, 3000, NULL),
(3001, 'furthermore', '/ˌfɜːrðərˈmɔːr/', 'adverb', '{"zh-TW":["此外；而且"],"en":["in addition to what has been said"]}', NULL, 'furthermore, ...', '[{"en":"The plan is cost-effective; furthermore, it is easy to implement.","zh-TW":"該計畫具有成本效益；此外，它易於實施。"},{"en":"Furthermore, the data supports our conclusion.","zh-TW":"此外，數據支持我們的結論。"}]', '{"adverb":"furthermore"}', NULL, 4, 3001, NULL),
(3002, 'futile', '/''fjuːtɪl/', 'adjective', '{"zh-TW":["徒勞的；無用的"],"en":["producing no useful result; pointless"]}', NULL, 'futile attempt / futile effort / futile endeavor', '[{"en":"It would be futile to continue negotiating without a shared goal.","zh-TW":"在沒有共同目標的情況下繼續談判是徒勞的。"},{"en":"The team''s futile efforts to restore the corrupted data lasted two days.","zh-TW":"團隊恢復損壞數據的徒勞努力持續了兩天。"}]', '{"adverb":"futilely","noun":"futility"}', NULL, 2, 3002, NULL),
(3003, 'future', '/ˈfjuːtʃər/', 'noun', '{"zh-TW":["未來"],"en":["the time that will come"]}', NULL, 'in the future / future plans', '[{"en":"What are your future plans?","zh-TW":"你未來有什麼計畫？"},{"en":"We must invest for the future.","zh-TW":"我們必須為未來投資。"}]', '{"noun":"future","adjective":"future","adjective2":"futuristic"}', NULL, 2, 3003, NULL),
(3004, 'futures', '/ˈfjuːtʃərz/', 'noun', '{"zh-TW":["期貨"],"en":["contracts to buy or sell an asset at a predetermined future price"]}', NULL, 'futures contract / commodity futures / futures market / trade futures', '[{"en":"Oil futures fell sharply on oversupply concerns.","zh-TW":"由於供過於求的擔憂，石油期貨大幅下跌。"},{"en":"She hedged her position using futures contracts.","zh-TW":"她使用期貨合約對沖了自己的部位。"}]', NULL, NULL, 3, 3004, NULL),
(3005, 'fuzzing', '/ˈfʌzɪŋ/', 'noun', '{"zh-TW":["模糊測試"],"en":["a technique that tests software by providing random, invalid inputs to find bugs"]}', NULL, 'perform fuzzing / fuzzing tool / automated fuzzing', '[{"en":"Security teams use fuzzing to discover vulnerabilities before attackers do.","zh-TW":"安全團隊使用模糊測試在攻擊者之前發現漏洞。"},{"en":"Fuzzing is especially useful for testing network protocols and file parsers.","zh-TW":"模糊測試對於測試網絡協議和文件解析器特別有用。"}]', '{"verb":"fuzz","adjective":"fuzzed"}', NULL, 3, 3005, NULL),
(3006, 'gadget', '/ˈɡædʒɪt/', 'noun', '{"zh-TW":["小工具；小裝置"],"en":["a small mechanical or electronic device"]}', NULL, 'kitchen gadget / tech gadget', '[{"en":"He loves buying new gadgets.","zh-TW":"他喜歡買新的科技小裝置。"},{"en":"This gadget makes cooking easier.","zh-TW":"這個小工具讓做飯更容易。"}]', NULL, NULL, 2, 3006, NULL),
(3007, 'gain', '/ɡeɪn/', 'verb / noun', '{"zh-TW":["獲得；增益"],"en":["to obtain; an increase in amount"]}', NULL, 'gain experience/access', '[{"en":"She gained valuable experience abroad.","zh-TW":"她在國外獲得了寶貴的經驗。"},{"en":"The company reported significant gains.","zh-TW":"公司報告了顯著的收益。"}]', '{"noun":"gain","verb":"gain"}', NULL, 1, 3007, NULL),
(3008, 'gain on disposal', '/ɡeɪn ɒn dɪˈspoʊzəl/', 'noun', '{"zh-TW":["出售收益；處置收益"],"en":["profit made from selling an asset for more than its book value"]}', NULL, 'record a gain on disposal / realize a gain on disposal', '[{"en":"The sale of the building resulted in a gain on disposal of 5 million.","zh-TW":"出售大樓帶來了500萬元的處置收益。"},{"en":"Gains on disposal are recorded in the income statement.","zh-TW":"出售收益在損益表中記錄。"}]', NULL, NULL, 5, 3008, NULL),
(3009, 'gala', '/ˈɡɑːlə/', 'noun', '{"zh-TW":["盛典；晚宴"],"en":["a festive occasion, especially an elaborate celebration"]}', NULL, 'charity gala / annual gala dinner', '[{"en":"The charity gala raised over a million dollars.","zh-TW":"慈善晚宴籌集了超過一百萬元。"},{"en":"The company held its annual gala to celebrate its 50th anniversary.","zh-TW":"公司舉辦了年度盛典慶祝成立50週年。"}]', NULL, NULL, 1, 3009, NULL),
(3010, 'gallery', '/ˈɡæləri/', 'noun', '{"zh-TW":["畫廊；美術館"],"en":["a room or building for displaying works of art"]}', '{"root":{"text":"gallery","meaning":"porch/corridor (走廊)"},"logic":"源自中世紀拉丁語 galeria（走廊），後指展示藝術品的空間。"}', 'art gallery / photo gallery', '[{"en":"We visited an art gallery downtown.","zh-TW":"我們參觀了市中心的一家畫廊。"},{"en":"The gallery features local artists.","zh-TW":"這家畫廊展出本地藝術家的作品。"}]', NULL, NULL, 3, 3010, NULL),
(3011, 'game', '/ɡeɪm/', 'noun', '{"zh-TW":["遊戲；比賽"],"en":["an activity for fun or competition"]}', NULL, 'game plan / ahead of the game', '[{"en":"What is our game plan for next quarter?","zh-TW":"我們下一季的策略是什麼？"},{"en":"Stay ahead of the game.","zh-TW":"保持領先。"}]', '{"noun":"game","noun2":"gamer","noun3":"gaming"}', NULL, 1, 3011, NULL),
(3012, 'game plan', '/''ɡeɪm plæn/', 'noun', '{"zh-TW":["比賽策略；作戰計劃"],"en":["a strategy worked out in advance for achieving a goal, especially in sports"]}', NULL, 'develop a game plan / follow the game plan / adapt the game plan', '[{"en":"The coach developed a game plan specifically designed to exploit the opponent''s weaknesses.","zh-TW":"教練制定了一個專門針對對手弱點的比賽策略。"},{"en":"When their game plan failed, the team had to improvise new tactics.","zh-TW":"當他們的比賽策略失敗時，球隊不得不即興制定新戰術。"}]', NULL, NULL, 3, 3012, NULL),
(3013, 'game theory', '/ɡeɪm ˈθɪəri/', 'noun', '{"zh-TW":["博弈論"],"en":["the study of strategic decision-making in competitive situations"]}', NULL, 'apply game theory / game theory model / game theory in economics', '[{"en":"Game theory predicts how rational agents make decisions in competitive settings.","zh-TW":"博弈論預測理性主體在競爭環境中如何做決策。"},{"en":"Auction design is a direct application of game theory in practice.","zh-TW":"拍賣設計是博弈論在實踐中的直接應用。"}]', NULL, NULL, 4, 3013, NULL),
(3014, 'gap', '/ɡæp/', 'noun', '{"zh-TW":["差距；缺口"],"en":["a space between; a difference"]}', NULL, 'bridge/close the gap', '[{"en":"There is a gap between supply and demand.","zh-TW":"供需之間有差距。"},{"en":"We need to bridge the skills gap.","zh-TW":"我們需要彌補技能差距。"}]', '{"noun":"gap"}', NULL, 1, 3014, NULL),
(3015, 'gap year', '/''ɡæp jɪər/', 'noun', '{"zh-TW":["空檔年；間隔年"],"en":["a period, typically an academic year, taken by a student as a break between school and university"]}', NULL, 'take a gap year / gap year travel / gap year program', '[{"en":"She took a gap year to volunteer in Africa before starting university.","zh-TW":"她在開始大學學習之前，利用空檔年在非洲做義工。"},{"en":"A gap year can help students mature and discover what they truly want to study.","zh-TW":"空檔年可以幫助學生成長並發現他們真正想學什麼。"}]', NULL, NULL, 3, 3015, NULL),
(3016, 'garden', '/ˈɡɑːrdən/', 'noun', '{"zh-TW":["花園"],"en":["a piece of land for growing plants"]}', NULL, 'rooftop garden / garden party', '[{"en":"The hotel has a beautiful rooftop garden.","zh-TW":"飯店有一個漂亮的屋頂花園。"},{"en":"They held a garden party for staff.","zh-TW":"他們為員工舉辦了花園派對。"}]', '{"noun":"garden","noun2":"gardener","noun3":"gardening","verb":"garden"}', NULL, 2, 3016, NULL),
(3017, 'garden suite', '/ˈɡɑːrdən swiːt/', 'noun', '{"zh-TW":["花園套房"],"en":["a hotel suite with access to or views of a garden"]}', NULL, 'book a garden suite / private garden suite', '[{"en":"The garden suite has a private patio overlooking the grounds.","zh-TW":"花園套房設有可俯瞰庭院的私人露台。"},{"en":"They chose the garden suite for its peaceful outdoor setting.","zh-TW":"他們選擇了花園套房，因為其寧靜的戶外環境。"}]', NULL, NULL, 4, 3017, NULL),
(3018, 'garnish', '/ˈɡɑːrnɪʃ/', 'noun', '{"zh-TW":["裝飾；配菜"],"en":["an item used to decorate or add flavor to a dish"]}', NULL, 'fresh garnish / add a garnish', '[{"en":"The dish is served with a lemon garnish.","zh-TW":"這道菜配上檸檬裝飾。"},{"en":"The chef added a herb garnish to the soup.","zh-TW":"廚師在湯裡加了香草裝飾。"}]', '{"verb":"garnish"}', NULL, 3, 3018, NULL),
(3019, 'garnishment', '/ˈɡɑːrnɪʃmənt/', 'noun', '{"zh-TW":["薪資扣押；財產扣押令"],"en":["a legal process by which a creditor collects debts by seizing assets held by a third party"]}', NULL, 'wage garnishment / bank garnishment / garnishment order', '[{"en":"The court issued a wage garnishment order against the debtor.","zh-TW":"法院對債務人發出了薪資扣押令。"},{"en":"Garnishment is a common enforcement mechanism for unpaid judgments.","zh-TW":"扣押是未付判決的常見執行機制。"}]', '{"verb":"garnish"}', NULL, 4, 3019, NULL),
(3020, 'gastroenterologist', '/ˌɡæstrəʊˌentəˈrɒlədʒɪst/', 'noun', '{"zh-TW":["腸胃科醫師"],"en":["a specialist in diseases of the stomach and intestines"]}', NULL, 'consult a gastroenterologist / specialist gastroenterologist / experienced gastroenterologist', '[{"en":"The gastroenterologist performed a colonoscopy to investigate the symptoms.","zh-TW":"腸胃科醫師進行了結腸鏡檢查以調查症狀。"},{"en":"Persistent digestive issues should be evaluated by a gastroenterologist.","zh-TW":"持續的消化問題應由腸胃科醫師評估。"}]', NULL, NULL, 5, 3020, NULL),
(3021, 'gastronomy', '/''ɡæsˈtrɒnəmi/', 'noun', '{"zh-TW":["美食學；烹飪藝術"],"en":["the practice or art of choosing, cooking, and eating good food"]}', NULL, 'modern gastronomy / molecular gastronomy / study gastronomy', '[{"en":"Molecular gastronomy uses science to transform the texture and appearance of food.","zh-TW":"分子美食學利用科學來改變食物的質地和外觀。"},{"en":"The city is a hub of gastronomy, attracting food lovers from around the world.","zh-TW":"這座城市是美食學的中心，吸引著來自世界各地的美食愛好者。"}]', '{"adjective":"gastronomic","noun":"gastronome"}', NULL, 4, 3021, NULL),
(3022, 'gate', '/ɡeɪt/', 'noun', '{"zh-TW":["登機門；閘口"],"en":["an entrance to an airport departure area"]}', NULL, 'boarding gate / departure gate', '[{"en":"Passengers should proceed to gate twelve.","zh-TW":"旅客應前往十二號登機門。"},{"en":"The gate will close thirty minutes before departure.","zh-TW":"登機門將在出發前三十分鐘關閉。"}]', NULL, NULL, 1, 3022, NULL),
(3023, 'gather', '/ˈɡæðər/', 'verb', '{"zh-TW":["收集；聚集"],"en":["to bring together; to collect information"]}', NULL, 'gather information/data', '[{"en":"We gathered data from multiple sources.","zh-TW":"我們從多個來源收集了數據。"},{"en":"The team gathered to discuss the issue.","zh-TW":"團隊聚集起來討論這個問題。"}]', '{"noun":"gathering","verb":"gather"}', NULL, 2, 3023, NULL),
(3024, 'gauge', '/ɡeɪdʒ/', 'verb / noun', '{"zh-TW":["衡量；測量器"],"en":["to estimate or measure; a measuring instrument"]}', NULL, 'gauge interest/response', '[{"en":"It''s difficult to gauge customer interest.","zh-TW":"很難衡量客戶興趣。"},{"en":"The survey gauged employee satisfaction.","zh-TW":"調查衡量了員工滿意度。"}]', '{"noun":"gauge","verb":"gauge"}', NULL, 2, 3024, NULL),
(3025, 'GDP', '/ˌdʒiː diː ˈpiː/', 'noun', '{"zh-TW":["國內生產總值"],"en":["gross domestic product; the total value of goods and services produced in a country"]}', NULL, 'GDP growth / GDP per capita / measure GDP', '[{"en":"The country''s GDP grew by 3% in the last fiscal year.","zh-TW":"該國上一財政年度的GDP增長了3%。"},{"en":"GDP is the most widely used measure of economic performance.","zh-TW":"GDP是最廣泛使用的經濟績效衡量標準。"}]', '{"full form":"gross domestic product"}', NULL, 1, 3025, NULL),
(3026, 'gearing', '/ˈɡɪərɪŋ/', 'noun', '{"zh-TW":["財務槓桿比率"],"en":["the ratio of a company''s debt to its equity"]}', NULL, 'high gearing / low gearing / gearing ratio', '[{"en":"High gearing increases the risk of default during downturns.","zh-TW":"高財務槓桿增加了經濟低迷時違約的風險。"},{"en":"The company reduced its gearing by paying down long-term debt.","zh-TW":"公司通過償還長期債務降低了財務槓桿。"}]', '{"adjective":"geared","verb":"gear"}', NULL, 3, 3026, NULL),
(3027, 'gender pay gap', '/ˈdʒendər peɪ ɡæp/', 'noun', '{"zh-TW":["性別薪資差距"],"en":["the difference in average earnings between men and women"]}', NULL, 'close the gender pay gap / report the gender pay gap', '[{"en":"The company published its gender pay gap report as required by law.","zh-TW":"公司按法律要求發布了性別薪資差距報告。"},{"en":"Addressing the gender pay gap requires systemic organizational change.","zh-TW":"解決性別薪資差距需要系統性的組織變革。"}]', NULL, NULL, 5, 3027, NULL),
(3028, 'general', '/ˈdʒenərəl/', 'adjective', '{"zh-TW":["一般的；總體的"],"en":["affecting or including all; not specific"]}', NULL, 'in general / general manager', '[{"en":"In general, sales have been improving.","zh-TW":"一般來說，銷售一直在改善。"},{"en":"The general consensus is to proceed.","zh-TW":"普遍共識是繼續進行。"}]', '{"noun":"generalization","verb":"generalize","adjective":"general","adverb":"generally"}', NULL, 3, 3028, NULL),
(3029, 'general expenses', '/ˈdʒenərəl ɪkˈspensɪz/', 'noun', '{"zh-TW":["一般費用；日常開支"],"en":["routine operating costs not specifically assigned to a project"]}', NULL, 'control general expenses / reduce general expenses', '[{"en":"General expenses rose 10% due to higher utilities and rent.","zh-TW":"由於水電費和租金上漲，一般費用增加了10%。"},{"en":"The finance team tracks general expenses monthly against budget.","zh-TW":"財務團隊每月按預算追蹤一般費用。"}]', NULL, NULL, 5, 3029, NULL),
(3030, 'general ledger', '/ˈdʒɛnərəl ˈlɛdʒər/', 'noun', '{"zh-TW":["總帳；分類帳"],"en":["the primary accounting record of a company"]}', NULL, 'record in the general ledger / general ledger balance', '[{"en":"All transactions are posted to the general ledger.","zh-TW":"所有交易都記錄在總帳中。"},{"en":"The accountant reconciled the general ledger at month end.","zh-TW":"會計師在月底對總帳進行了核對。"}]', NULL, NULL, 5, 3030, NULL),
(3031, 'general manager', '/ˈdʒenərəl ˈmænɪdʒər/', 'noun', '{"zh-TW":["總經理"],"en":["a senior manager responsible for the overall operations of a business"]}', NULL, 'report to the general manager / become a general manager', '[{"en":"The general manager reviewed performance results with each department.","zh-TW":"總經理與每個部門回顧了績效結果。"},{"en":"She was appointed as general manager for the Asian division.","zh-TW":"她被任命為亞洲部門的總經理。"}]', '{"abbreviation":"GM"}', NULL, 5, 3031, NULL),
(3032, 'general practitioner', '/ˈdʒɛnərəl prækˈtɪʃənər/', 'noun', '{"zh-TW":["全科醫生；家庭醫生"],"en":["a doctor who treats patients with various conditions"]}', NULL, 'visit a general practitioner / refer to a specialist', '[{"en":"See your general practitioner before consulting a specialist.","zh-TW":"在諮詢專科醫生之前先看全科醫生。"},{"en":"A general practitioner provides primary care for all age groups.","zh-TW":"全科醫生為所有年齡組提供基層醫療。"}]', '{"abbreviation":"GP"}', NULL, 5, 3032, NULL),
(3033, 'generalize', '/ˈdʒenərəlaɪz/', 'verb', '{"zh-TW":["概括；推廣"],"en":["to make general or broad statements based on specific cases"]}', NULL, 'generalize findings / generalize from data / generalize results', '[{"en":"Be careful not to generalize from a small sample size.","zh-TW":"小心不要從小樣本進行概括推論。"},{"en":"The model generalizes well to unseen data.","zh-TW":"該模型能很好地推廣到未見過的數據。"}]', '{"noun":"generalization","adjective":"generalizable"}', NULL, 4, 3033, NULL),
(3034, 'generate', '/ˈdʒenəreɪt/', 'verb', '{"zh-TW":["產生；創造","產生；生成"],"en":["to produce or create"]}', '{"root":{"text":"gener","meaning":"birth/produce (生產)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其產生，即「生成」。"}', 'generate revenue/ideas; generate revenue / generate electricity / generate ideas', '[{"en":"The campaign generated significant revenue.","zh-TW":"該活動產生了可觀的收入。"},{"en":"Solar panels generate clean energy.","zh-TW":"太陽能板產生清潔能源。"},{"en":"The project will generate new jobs.","zh-TW":"這個專案將創造新的就業機會。"},{"en":"Solar panels generate electricity from sunlight.","zh-TW":"太陽能板從陽光產生電力。"}]', '{"noun":"generation/generator","verb":"generate","noun2":"generator"}', NULL, 3, 3034, 128),
(3035, 'generative AI', '/ˈdʒenərətɪv eɪ aɪ/', 'noun', '{"zh-TW":["生成式人工智慧"],"en":["a type of AI that creates new content such as text, images, or audio"]}', NULL, 'use generative AI / generative AI model / generative AI application', '[{"en":"Generative AI can produce realistic text, images, and video content.","zh-TW":"生成式人工智慧可以生成逼真的文字、圖像和影片內容。"},{"en":"Businesses are exploring generative AI for content creation and automation.","zh-TW":"企業正在探索將生成式人工智慧用於內容創作和自動化。"}]', NULL, NULL, 5, 3035, NULL),
(3036, 'generativity', '/ˌdʒenəˈrætɪvɪti/', 'noun', '{"zh-TW":["生產力；創造能力"],"en":["the ability to produce or create new ideas, content, or things"]}', NULL, 'AI generativity / creative generativity / cultural generativity', '[{"en":"The generativity of large language models challenges traditional content production.","zh-TW":"大型語言模型的生成能力挑戰了傳統內容生產方式。"},{"en":"Generativity in older adults is associated with well-being and life satisfaction.","zh-TW":"老年人的生產能力與幸福感和生活滿意度相關。"}]', '{"adjective":"generative"}', NULL, 4, 3036, NULL),
(3037, 'generic drug', '/dʒɪˈnɛrɪk drʌɡ/', 'noun', '{"zh-TW":["學名藥；仿製藥"],"en":["a medicine identical to a brand-name drug but cheaper"]}', NULL, 'switch to a generic drug / generic drug option', '[{"en":"Ask your pharmacist for a generic drug to save money.","zh-TW":"請詢問藥師是否有學名藥可節省費用。"},{"en":"Generic drugs are required to meet the same standards as brand-name drugs.","zh-TW":"學名藥必須符合與品牌藥相同的標準。"}]', NULL, NULL, 4, 3037, NULL),
(3038, 'generous', '/ˈdʒenərəs/', 'adjective', '{"zh-TW":["慷慨的；豐厚的","慷慨的；大方的"],"en":["willing to give more than expected","willing to give more than is expected"]}', '{"root":{"text":"gener","meaning":"birth/kind (出身/種類)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"出身高貴而樂於給予的，即「慷慨的」。"}', 'generous offer/donation; generous donation / generous offer', '[{"en":"The company offers generous benefits.","zh-TW":"公司提供豐厚的福利。"},{"en":"It was a generous donation.","zh-TW":"這是一筆慷慨的捐贈。"},{"en":"She is very generous with her time.","zh-TW":"她很慷慨地付出時間。"},{"en":"That was a generous donation.","zh-TW":"那是一筆慷慨的捐款。"}]', '{"noun":"generosity","adjective":"generous","adverb":"generously"}', NULL, 3, 3038, NULL),
(3039, 'genre bending', '/ˈʒɑːnrə ˈbendɪŋ/', 'noun', '{"zh-TW":["跨越類型；融合風格"],"en":["mixing or subverting established genre conventions"]}', NULL, 'genre-bending film / genre-bending fiction / genre-bending music', '[{"en":"Her genre-bending debut album defied easy categorization.","zh-TW":"她的跨越類型的首張專輯難以被簡單分類。"},{"en":"Genre-bending works attract diverse audiences who enjoy unexpected combinations.","zh-TW":"跨越類型的作品吸引了享受意外組合的多元受眾。"}]', '{"adjective":"genre-bending"}', NULL, 5, 3039, NULL),
(3040, 'gentrification', '/ˌdʒentrɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["士紳化；縉紳化"],"en":["the process of renovating urban areas, leading to displacement of existing residents"]}', NULL, 'gentrification of neighborhoods / rapid gentrification / gentrification debate', '[{"en":"Gentrification has priced many long-term residents out of their neighborhoods.","zh-TW":"士紳化使許多長期居民負擔不起居住在原本社區的費用。"},{"en":"The city''s gentrification sparked protests from community advocacy groups.","zh-TW":"城市的士紳化引發了社區倡導團體的抗議。"}]', '{"verb":"gentrify","adjective":"gentrified"}', NULL, 5, 3040, NULL),
(3041, 'genuine', '/ˈdʒenjuɪn/', 'adjective', '{"zh-TW":["真正的；真誠的"],"en":["truly what it is said to be; sincere","truly what something is said to be; authentic"]}', '{"root":{"text":"genu","meaning":"birth/native (天生)"},"suffix":{"text":"-ine","meaning":"relating to (相關的)"},"logic":"與天生本性相關的，即「真正的」。"}', 'genuine concern/interest; genuine interest / genuine concern / genuine article', '[{"en":"She showed genuine interest in the project.","zh-TW":"她對該項目表現出真誠的興趣。"},{"en":"Is this a genuine product?","zh-TW":"這是正品嗎？"},{"en":"She showed genuine interest in the topic.","zh-TW":"她對這個話題表現出真正的興趣。"},{"en":"Is this a genuine Picasso painting?","zh-TW":"這是真的畢卡索畫作嗎？"}]', '{"adjective":"genuine","adverb":"genuinely"}', NULL, 3, 3041, NULL),
(3042, 'geoengineering', '/ˌdʒiːəʊˌendʒɪˈnɪərɪŋ/', 'noun', '{"zh-TW":["地球工程"],"en":["deliberate large-scale intervention in the Earth''s climate to counteract global warming"]}', NULL, 'solar geoengineering / carbon geoengineering / debate over geoengineering', '[{"en":"Geoengineering proposals include reflecting sunlight to cool the planet.","zh-TW":"地球工程提案包括反射陽光以冷卻地球。"},{"en":"Critics warn that geoengineering could have unpredictable side effects.","zh-TW":"批評者警告說地球工程可能有不可預測的副作用。"}]', '{"adjective":"geoengineered"}', NULL, 5, 3042, NULL),
(3043, 'geopolitical', '/''dʒiːəʊpəˌlɪtɪkəl/', 'adjective', '{"zh-TW":["地緣政治的"],"en":["relating to politics, especially international relations, as influenced by geographical factors"]}', NULL, 'geopolitical risk / geopolitical tension / geopolitical shift', '[{"en":"Trade relationships are increasingly affected by geopolitical tensions between major powers.","zh-TW":"貿易關係越來越受到大國之間地緣政治緊張關係的影響。"},{"en":"The company assessed geopolitical risks before expanding operations into the region.","zh-TW":"公司在將業務擴展到該地區之前評估了地緣政治風險。"}]', '{"adverb":"geopolitically","noun":"geopolitics"}', NULL, 4, 3043, NULL),
(3044, 'geopolitics', '/ˌdʒiːəʊˈpɒlɪtɪks/', 'noun', '{"zh-TW":["地緣政治學"],"en":["politics, especially international relations, influenced by geographic factors"]}', NULL, 'geopolitics of energy / shifting geopolitics / impact of geopolitics', '[{"en":"Geopolitics shapes trade routes and investment flows globally.","zh-TW":"地緣政治塑造了全球貿易路線和投資流動。"},{"en":"Rising geopolitical tensions increased volatility in commodity markets.","zh-TW":"地緣政治緊張局勢加劇了大宗商品市場的波動性。"}]', '{"adjective":"geopolitical","adverb":"geopolitically"}', NULL, 4, 3044, NULL),
(3045, 'gestation', '/dʒeˈsteɪʃən/', 'noun', '{"zh-TW":["孕育期；醞釀期"],"en":["the process of developing over time before becoming active; pregnancy period"]}', NULL, 'long gestation / gestation period / gestation of an idea', '[{"en":"The infrastructure project had a long gestation period of over ten years before approval.","zh-TW":"這個基礎設施項目在獲批之前經歷了超過十年的漫長孕育期。"},{"en":"Policy reforms often have a lengthy gestation before being enacted into law.","zh-TW":"政策改革在立法實施之前往往需要經歷漫長的醞釀期。"}]', '{"adjective":"gestational"}', NULL, 3, 3045, NULL),
(3046, 'gesture', '/ˈdʒestʃər/', 'noun', '{"zh-TW":["姿態；表示"],"en":["a movement or action to express an idea; a kind act"]}', NULL, 'a goodwill gesture', '[{"en":"The bonus was a gesture of appreciation.","zh-TW":"獎金是一種感謝的表示。"},{"en":"It was a kind gesture from the management.","zh-TW":"這是管理層善意的姿態。"}]', '{"noun":"gesture","verb":"gesture"}', NULL, 3, 3046, NULL),
(3047, 'gift', '/ɡɪft/', 'noun', '{"zh-TW":["禮物；天賦"],"en":["something given freely","a natural talent"]}', NULL, 'gift card / gift wrap', '[{"en":"We offer gift cards for loyal customers.","zh-TW":"我們為忠實客戶提供禮品卡。"},{"en":"She has a gift for communication.","zh-TW":"她有溝通的天賦。"}]', '{"noun":"gift","adjective":"gifted"}', NULL, 1, 3047, NULL),
(3048, 'give', 'ɡɪv', 'verb', '{"zh-TW":["給予；提供","發表"],"en":["to hand something to someone","to present"]}', NULL, 'give feedback/a presentation', '[{"en":"She gave a speech at the conference.","zh-TW":"她在會議上發表了演講。"}]', '{"noun":"giver, gift","adjective":"giving"}', NULL, 1, 3048, NULL),
(3049, 'glacier', '/''ɡlæsiər/', 'noun', '{"zh-TW":["冰河；冰川"],"en":["a slowly moving mass of ice formed by the accumulation of snow on mountains"]}', NULL, 'melting glacier / visit a glacier / glacier retreat', '[{"en":"Climate change is causing glaciers around the world to melt at an alarming rate.","zh-TW":"氣候變化正導致世界各地的冰川以驚人速度融化。"},{"en":"Hiking on the glacier required special equipment and a guide.","zh-TW":"在冰川上徒步需要特殊裝備和嚮導。"}]', NULL, NULL, 3, 3049, NULL);